  `main_id` bigint NOT NULL COMMENT '主表ID',
  `sort` int NOT NULL COMMENT '序号',
  `name` varchar(32) NOT NULL COMMENT '名称',
  `field` varchar(32) NOT NULL COMMENT '字段',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `status` varchar(100) DEFAULT NULL COMMENT '是否隐藏',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=180 DEFAULT CHARSET=utf8 COMMENT='数据源字段表';

-- ----------------------------
-- Records of inte_data_source_field
-- ----------------------------

