  `data_source_name` varchar(64) NOT NULL COMMENT '数据源名称',
  `souce_bill` varchar(64) NOT NULL COMMENT '源单名称',
  `target_bill` varchar(64) NOT NULL COMMENT '目标单据',
  `status` varchar(100) DEFAULT NULL COMMENT '状态',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=35 DEFAULT CHARSET=utf8 COMMENT='集成方案';

-- ----------------------------
-- Records of inte_plan
-- ----------------------------

-- ----------------------------
-- Table structure for inte_plan_field
-- ----------------------------
DROP TABLE IF EXISTS `inte_plan_field`;
CREATE TABLE `inte_plan_field` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `main_id` bigint NOT NULL COMMENT '主表ID',
  `sort` int NOT NULL COMMENT '序号',
  `mes_name` varchar(32) NOT NULL COMMENT 'mes字段名称',
  `mes_field` varchar(32) NOT NULL COMMENT 'mes字段',
  `souce_name` varchar(64) DEFAULT NULL COMMENT '源单字段名称',
  `souce_field` varchar(32) DEFAULT NULL COMMENT '源单字段',
  `isQuery` varchar(64) DEFAULT NULL COMMENT '是否查询',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
