-- Records of md_bom
-- ----------------------------

-- ----------------------------
-- Table structure for md_customer
-- ----------------------------
DROP TABLE IF EXISTS `md_customer`;
CREATE TABLE `md_customer` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `number` varchar(64) DEFAULT NULL COMMENT '编号',
  `name` varchar(64) NOT NULL COMMENT '名称',
  `name_abb` varchar(64) DEFAULT NULL COMMENT '简称',
  `name_en` varchar(64) DEFAULT NULL COMMENT '英文名',
  `cus_describe` varchar(512) DEFAULT NULL COMMENT '简介',
  `type` varchar(64) NOT NULL DEFAULT 'B' COMMENT '类型',
  `logo` varchar(255) DEFAULT NULL COMMENT 'logo',
  `address` varchar(512) DEFAULT NULL COMMENT '地址',
  `website` varchar(255) DEFAULT NULL COMMENT '官网',
  `email` varchar(255) DEFAULT NULL COMMENT '邮箱',
  `phone` varchar(64) DEFAULT NULL COMMENT '电话',
  `contacts` varchar(64) DEFAULT NULL COMMENT '联系人',
  `contacts_phone` varchar(64) DEFAULT NULL COMMENT '联系人电话',
  `contacts_email` varchar(255) DEFAULT NULL COMMENT '联系人邮箱',
  `contactsb` varchar(64) DEFAULT NULL COMMENT '联系人2',
  `contactsb_phone` varchar(64) DEFAULT NULL COMMENT '联系人2电话',
  `contactsb_email` varchar(255) DEFAULT NULL COMMENT '联系人2邮箱',
  `credit_code` varchar(64) DEFAULT NULL COMMENT '社会统一信用代码',
  `status` varchar(100) NOT NULL DEFAULT '0' COMMENT '状态',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(32) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=136 DEFAULT CHARSET=utf8 COMMENT='客户表';

