  `specification` varchar(32) DEFAULT NULL COMMENT '规格型号',
  `unit_id` bigint NOT NULL COMMENT '计量单位',
  `class_id` bigint NOT NULL COMMENT '物料分类',
  `type_id` varchar(100) NOT NULL DEFAULT 'A' COMMENT '物料类型',
  `status` varchar(100) NOT NULL DEFAULT '0' COMMENT '状态',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
