-- ----------------------------
-- Table structure for pro_report
-- ----------------------------
DROP TABLE IF EXISTS `pro_report`;
CREATE TABLE `pro_report` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `number` varchar(64) DEFAULT NULL,
  `work_order_entry_id` bigint NOT NULL COMMENT '工单子表ID',
  `report_user_id` bigint NOT NULL COMMENT '报工人ID',
  `report_user_name` varchar(255) NOT NULL COMMENT '报工人名称',
  `report_channel` varchar(64) NOT NULL DEFAULT 'PC' COMMENT '报工途径',
  `status` varchar(32) NOT NULL DEFAULT 'A' COMMENT '状态',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(32) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `report_time` datetime NOT NULL COMMENT '报工时间',
  `report_quantity` decimal(9,3) NOT NULL COMMENT '报工数量',
  `qualified_quantity` decimal(9,3) DEFAULT NULL COMMENT '合格数量',
  `unqualified_quantity` decimal(9,3) DEFAULT NULL COMMENT '不合格数量',
  `workshop_id` bigint DEFAULT NULL COMMENT '车间ID',
  `workshop_name` varchar(64) DEFAULT NULL COMMENT '车间名称',
  `station_id` bigint DEFAULT NULL COMMENT '工位ID',
  `station_name` varchar(64) DEFAULT NULL COMMENT '工位名称',
  `is_settle` varchar(64) NOT NULL DEFAULT 'N' COMMENT '是否结算工资',
  `wages` decimal(9,3) NOT NULL DEFAULT '0.000' COMMENT '结算工资',
  `quality_status` varchar(64) DEFAULT NULL COMMENT '质检状态',
  `sn_array` text COMMENT 'SN码数组',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='报工单';

-- ----------------------------
-- Records of pro_report
-- ----------------------------

-- ----------------------------
-- Table structure for pro_route
