  `route_id` bigint NOT NULL COMMENT '工序路线id',
  `process_id` bigint NOT NULL COMMENT '工序id',
  `process_name` varchar(32) NOT NULL COMMENT '工序名',
  `sort` int NOT NULL COMMENT '工序顺序',
  `next_rule` varchar(10) DEFAULT NULL COMMENT '工序关系',
  `status` varchar(100) DEFAULT NULL COMMENT '状态',
  `create_by` varchar(32) DEFAULT NULL COMMENT '创建人',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `qc_type` varchar(2) DEFAULT NULL COMMENT '质检类型',
  `first_qc_quantity` decimal(10,3) DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8 COMMENT='工序路线明细';

