-- Records of pro_route_process
-- ----------------------------

-- ----------------------------
-- Table structure for pro_workorder
-- ----------------------------
DROP TABLE IF EXISTS `pro_workorder`;
CREATE TABLE `pro_workorder` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `number` varchar(255) NOT NULL COMMENT '编号',
  `priority` int DEFAULT NULL COMMENT '优先级',
  `annex` varchar(2048) DEFAULT NULL COMMENT '附件',
  `name` varchar(255) DEFAULT NULL COMMENT '工单名称',
  `source_type` varchar(255) DEFAULT NULL COMMENT '来源类型',
  `source_system` varchar(255) DEFAULT NULL COMMENT '来源系统',
  `source_info` text COMMENT '来源信息',
  `batch_number` varchar(255) DEFAULT NULL COMMENT '批次号',
  `material_id` bigint NOT NULL COMMENT '产品ID',
  `material_number` varchar(255) DEFAULT NULL COMMENT '产品编号',
  `material_name` varchar(255) NOT NULL COMMENT '产品名称',
  `specification` varchar(2048) DEFAULT NULL,
  `material_unit_id` bigint NOT NULL COMMENT '单位ID',
  `material_unit_name` varchar(255) NOT NULL COMMENT '单位名称',
  `quantity` decimal(10,3) NOT NULL COMMENT '生产数量',
  `begin_pro_date` date DEFAULT NULL COMMENT '开始生产日期',
  `plan_finish_date` date DEFAULT NULL COMMENT '计划完成日期',
  `real_finish_date` date DEFAULT NULL COMMENT '实际完成日期',
  `pro_status` varchar(64) DEFAULT NULL COMMENT '生产状态',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(32) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `status` varchar(100) NOT NULL DEFAULT 'A' COMMENT '状态',
  `is_postpone` varchar(32) NOT NULL DEFAULT 'N' COMMENT '是否超期',
  `repair_flag` varchar(32) DEFAULT 'N' COMMENT '返修标记',
  `extend_field` text COMMENT '扩展字段',
  `custom_sort` int DEFAULT NULL COMMENT '自定义排序',
  PRIMARY KEY (`id`),
  UNIQUE KEY `number_unique` (`number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='工单主表';

-- ----------------------------
-- Records of pro_workorder
-- ----------------------------

-- ----------------------------
-- Table structure for pro_workorder_entry
-- ----------------------------
DROP TABLE IF EXISTS `pro_workorder_entry`;
CREATE TABLE `pro_workorder_entry` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `workshop_id` bigint DEFAULT NULL COMMENT '车间ID',
  `workshop_name` varchar(255) DEFAULT NULL COMMENT '车间名称',
  `station_id` bigint DEFAULT NULL COMMENT '工位ID',
  `station_name` varchar(255) DEFAULT NULL COMMENT '工位名称',
  `workorder_id` bigint DEFAULT NULL COMMENT '工单ID',
  `process_id` bigint DEFAULT NULL COMMENT '工序ID',
  `process_name` varchar(255) DEFAULT NULL COMMENT '工序名称',
  `sort` int DEFAULT '1' COMMENT '排序',
  `qc_type` varchar(2) DEFAULT NULL COMMENT '质检类型',
  `first_qc_quantity` decimal(10,3) DEFAULT NULL,
  `type` varchar(36) DEFAULT NULL COMMENT '类型',
  `report_material_id` bigint DEFAULT NULL COMMENT '报工物料ID',
  `report_specification` varchar(255) DEFAULT NULL COMMENT '报工物料规格',
  `report_material_name` varchar(255) DEFAULT NULL COMMENT '报工物料名称',
  `report_quantity` decimal(10,0) DEFAULT NULL COMMENT '报工数量',
  `pick_material_id` bigint DEFAULT NULL COMMENT '领料ID',
  `pick_specification` varchar(255) DEFAULT NULL COMMENT '领料规格',
  `pick_material_name` varchar(255) DEFAULT NULL COMMENT '领料名称',
  `pick_quantity` decimal(10,0) DEFAULT NULL COMMENT '领料数量',
  `in_warehouse_id` bigint DEFAULT NULL COMMENT '入库ID',
  `in_warehouse_name` varchar(255) DEFAULT NULL COMMENT '入库名称',
  `out_warehouse_id` bigint DEFAULT NULL COMMENT '出库ID',
  `out_warehouse_name` varchar(255) DEFAULT NULL COMMENT '出库名称',
  `extend_field` text COMMENT '扩展字段',
  `machine_id` bigint DEFAULT NULL COMMENT '设备ID',
  `machine_name` varchar(64) DEFAULT NULL COMMENT '设备名称',
  `status` varchar(32) DEFAULT NULL COMMENT '完成状态',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `process_sort` int DEFAULT NULL COMMENT '工序顺序',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='工单子表';

-- ----------------------------
-- Records of pro_workorder_entry
-- ----------------------------

