-- ----------------------------
-- Table structure for qc_report_quality
-- ----------------------------
DROP TABLE IF EXISTS `qc_report_quality`;
CREATE TABLE `qc_report_quality` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `number` varchar(64) DEFAULT NULL COMMENT '编号',
  `report_ids` varchar(1024) NOT NULL COMMENT '报工单IDs',
  `report_number` varchar(64) DEFAULT NULL COMMENT '报工单编号',
  `work_order_number` varchar(64) DEFAULT NULL COMMENT '工单编号',
  `process_name` varchar(64) NOT NULL COMMENT '工序',
  `material_number` varchar(64) DEFAULT NULL COMMENT '产品编码',
  `material_name` varchar(64) NOT NULL COMMENT '产品名称',
  `specification` varchar(255) DEFAULT NULL COMMENT '规格型号',
  `material_unit_name` varchar(255) NOT NULL COMMENT '单位',
  `batch_number` varchar(64) DEFAULT NULL COMMENT '批次号',
  `qc_type` varchar(4) NOT NULL COMMENT '质检类型',
  `quantity` decimal(12,3) NOT NULL COMMENT '检测数量',
  `qualified_quantity` decimal(9,3) NOT NULL COMMENT '合格数量',
  `unqualified_quantity` decimal(9,3) NOT NULL DEFAULT '0.000' COMMENT '不合格数量',
  `report_time` datetime DEFAULT NULL COMMENT '报工时间',
  `check_time` datetime NOT NULL COMMENT '检测时间',
  `check_user_id` bigint NOT NULL COMMENT '质检员ID',
  `check_user_name` varchar(64) NOT NULL COMMENT '质检员名称',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(32) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `status` varchar(100) NOT NULL DEFAULT '0' COMMENT '状态',
  `sn_array` text COMMENT 'SN码数组',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='报工质检单';

