  `level_id` bigint NOT NULL COMMENT '等级ID',
  `level_name` varchar(255) DEFAULT NULL COMMENT '等级名称',
  `type` varchar(64) NOT NULL COMMENT '类型',
  `quantity` decimal(9,3) NOT NULL COMMENT '数量',
