-- ----------------------------
-- Table structure for sal_order
-- ----------------------------
DROP TABLE IF EXISTS `sal_order`;
CREATE TABLE `sal_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `number` varchar(32) DEFAULT NULL COMMENT '单号',
  `status` varchar(100) NOT NULL DEFAULT 'A' COMMENT '状态',
  `source_info` text COMMENT '源单信息',
  `logistics_number` varchar(500) DEFAULT NULL COMMENT '物流单号',
  `dept_id` bigint DEFAULT NULL COMMENT '销售部门id',
  `dept_name` varchar(32) DEFAULT NULL COMMENT '销售部门',
  `user_id` bigint DEFAULT NULL COMMENT '销售员id',
  `user_name` varchar(32) DEFAULT NULL COMMENT '销售员',
  `currency` varchar(100) NOT NULL DEFAULT 'RMB' COMMENT '结算币别',
  `sale_date` date NOT NULL COMMENT '销售日期',
  `customer_id` bigint DEFAULT NULL COMMENT '客户id',
  `customer_name` varchar(255) DEFAULT NULL COMMENT '客户',
  `consignee` varchar(32) DEFAULT NULL COMMENT '收货人',
  `consignee_phone` varchar(32) DEFAULT NULL COMMENT '收货电话',
  `consignee_department` varchar(32) DEFAULT NULL COMMENT '收货单位',
  `area` varchar(500) DEFAULT NULL COMMENT '区',
  `address` varchar(500) DEFAULT NULL COMMENT '详细地址',
  `annex` varchar(1024) DEFAULT NULL COMMENT '附件',
  `checker` varchar(32) DEFAULT NULL COMMENT '审核人',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(32) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `invoice_mark` varchar(2) DEFAULT NULL COMMENT '开票标记',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COMMENT='销售订单';

-- ----------------------------
-- Records of sal_order
-- ----------------------------

-- ----------------------------
-- Table structure for sal_order_entry
-- ----------------------------
DROP TABLE IF EXISTS `sal_order_entry`;
CREATE TABLE `sal_order_entry` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `sort` int DEFAULT NULL COMMENT '排序',
  `main_id` bigint NOT NULL COMMENT '主表id',
  `material_id` bigint NOT NULL COMMENT '物料id',
  `material_number` varchar(32) DEFAULT NULL COMMENT '物料编号',
  `material_name` varchar(32) NOT NULL COMMENT '物料名称',
  `material_specification` varchar(64) DEFAULT NULL COMMENT '规格型号',
  `material_class` varchar(32) DEFAULT NULL COMMENT '物料分类',
  `material_type` varchar(32) DEFAULT NULL COMMENT '物料类型',
  `unit_id` bigint NOT NULL COMMENT '单位id',
  `unit_name` varchar(32) NOT NULL COMMENT '单位名称',
  `quantity` decimal(10,3) NOT NULL DEFAULT '1.000' COMMENT '销售数量',
  `price` decimal(10,3) DEFAULT NULL COMMENT '单价',
  `tax_price` decimal(10,3) DEFAULT NULL COMMENT '含税单价',
  `discount` double(10,3) DEFAULT NULL COMMENT '折扣率',
  `is_gift` varchar(32) NOT NULL DEFAULT 'Y' COMMENT '是否赠品',
  `tax_rate` int DEFAULT NULL COMMENT '税率',
  `total_tax` decimal(10,3) DEFAULT NULL COMMENT '税额',
  `total_price` decimal(10,3) DEFAULT NULL COMMENT '金额',
  `total_tax_price` decimal(10,3) DEFAULT NULL COMMENT '价税合计',
  `need_date` date DEFAULT NULL COMMENT '要货日期',
  `delivery_date` date DEFAULT NULL COMMENT '发货日期',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(32) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `status` varchar(2) DEFAULT 'A',
  `extend_field` text COMMENT '扩展字段',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

-- ----------------------------
-- Records of sal_order_entry
-- ----------------------------

