  `date_format` varchar(64) DEFAULT NULL COMMENT '日期格式',
  `constant_char` varchar(32) DEFAULT NULL COMMENT '常量',
  `element_source_table` varchar(20) DEFAULT NULL COMMENT '元素键值',
  `source_attribute` varchar(32) DEFAULT NULL COMMENT '元素属性',
