-- ----------------------------
-- Table structure for sys_field_extend
-- ----------------------------
DROP TABLE IF EXISTS `sys_field_extend`;
CREATE TABLE `sys_field_extend` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `source_bill` varchar(100) DEFAULT NULL COMMENT '原单据',
  `sort` int DEFAULT NULL COMMENT '排序',
  `field` varchar(255) DEFAULT NULL COMMENT '字段名',
  `field_name` varchar(255) DEFAULT NULL COMMENT '字段文本',
  `type` varchar(32) DEFAULT NULL COMMENT '字段类型',
  `quote_data` varchar(255) DEFAULT NULL COMMENT '引用数据',
  `quote_field` varchar(255) DEFAULT NULL COMMENT '引用字段',
  `formula` varchar(1000) DEFAULT NULL COMMENT '计算公式',
  `is_required` varchar(32) DEFAULT NULL COMMENT '是否唯一',
  `is_must` varchar(32) DEFAULT NULL COMMENT '是否必录',
  `status` varchar(100) NOT NULL COMMENT '状态',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `create_by` varchar(32) NOT NULL COMMENT '创建人',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_by` varchar(32) DEFAULT NULL COMMENT '更新人',
  `update_time` datetime DEFAULT NULL COMMENT '更新时间',
  `width` int DEFAULT NULL,
  `default_value` varchar(255) DEFAULT NULL COMMENT '默认值',
  `is_system` varchar(2) DEFAULT 'N',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=99 DEFAULT CHARSET=utf8 COMMENT='字段扩展表';

