-- ----------------------------
-- View structure for real_time_inventory
-- ----------------------------
DROP VIEW IF EXISTS `real_time_inventory`;
CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`%` SQL SECURITY DEFINER VIEW `real_time_inventory` AS select sum(`b`.`quantity`) AS `aa`,`a`.`warehouse_id` AS `warehouse_id`,`a`.`warehouse_name` AS `warehouse_name`,`b`.`material_id` AS `material_id`,`b`.`material_number` AS `material_number`,`b`.`material_name` AS `material_name`,`b`.`material_unit_name` AS `material_unit_name` from (`wm_manufacture_into_entry` `b` left join `wm_manufacture_into` `a` on((`a`.`id` = `b`.`main_id`))) group by `a`.`warehouse_id`,`a`.`warehouse_name`,`b`.`material_id`,`b`.`material_number`,`b`.`material_name`,`b`.`material_unit_name` order by `a`.`warehouse_id`,`b`.`material_number` ;
